function resize(){view?.resize();const r=canvas.getBoundingClientRect();layer.width=Math.round(r.width*devicePixelRatio);layer.height=Math.round(r.height*devicePixelRatio);ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);drawAim();}
